// Writes docs/AUDIO_SCRIPT.md (the teacher's recording script) from src/audio/manifest.ts.
// Run: npm run audio:script   (Node 24 runs this TypeScript file directly.)
import { writeFileSync } from "node:fs";
import { CLIP_GROUPS } from "../src/audio/manifest.ts";

const lines: string[] = [
  "# Kịch bản thu âm — Thám tử Toán học Tí hon",
  "",
  "<!-- Generated by `npm run audio:script` from src/audio/manifest.ts. Do not edit by hand. -->",
  "",
  "Cô/thầy đọc từng câu dưới đây, mỗi câu lưu thành một tệp riêng, đặt tên đúng như cột **Tên tệp**,",
  "rồi chép vào thư mục `public/audio/`. Câu nào chưa thu, ứng dụng tạm dùng giọng đọc của máy (nếu có).",
  "",
  "Mẹo thu âm:",
  "- Đọc chậm, rõ, vui vẻ, như đang nói với các em lớp 1.",
  "- Mỗi tệp chỉ một câu; cắt bỏ khoảng lặng ở đầu và cuối.",
  "- Định dạng `.mp3`, mono, 44.1 kHz là đủ.",
  "- Các số và từ nối (“và”, “chục”, “nhé!”) được ghép với nhau, nên đọc chúng với giọng đều, không lên xuống quá nhiều.",
  "",
];
let total = 0;
for (const [group, clips] of Object.entries(CLIP_GROUPS)) {
  lines.push(`## ${group}`, "", "| Tên tệp | Câu cần đọc |", "| --- | --- |");
  for (const [id, text] of Object.entries(clips)) {
    lines.push(`| \`${id}.mp3\` | ${text} |`);
    total++;
  }
  lines.push("");
}
lines.push(`Tổng cộng: **${total}** tệp.`, "");
writeFileSync(new URL("../docs/AUDIO_SCRIPT.md", import.meta.url), lines.join("\n"), "utf8");
console.log(`docs/AUDIO_SCRIPT.md: ${total} clips`);
